    ('Uzm.Dr. AYGÜN HƏMİDOVA', 'uzm-dr-aygun-hemidova', 'obstetrics-gynecology', 'Azərbaycan Tibb Universiteti- Tibb Fakültəsi- 2005-2011 | Akdeniz Universiteti Tibb Fakültəsi - Qadın Xəstəlikləri və doğum uzmanlığı- 2015-2020', 15, NULL, '/doctor-photos/uzm-dr-aygun-hemidova.webp', 'az', 'UNCLAIMED', 'livhospital.az', 0, 1, NOW(), NOW()),
